def parse_valunc(s):
    m = re.match(r'([\d.]+)\s*\((\d+)\)', s.strip())
    if not m:
        return None, None
    v = float(m.group(1))
    u = int(m.group(2))
    if '.' in m.group(1):
        d = len(m.group(1).split('.')[1])
    else:
        d = 0
    return v, u / (10**d)


entries = []
for line in text:
    parts = line.split('|')
    e_val, e_unc = parse_valunc(parts[0])
    if len(parts) > 1 and parts[1].strip():
        i_val, i_unc = parse_valunc(parts[1])
    else:
        i_val, i_unc = None, None
    if e_val is not None and i_val is not None:
        entries.append((e_val, e_unc, i_val, i_unc))

print("=== I_gamma vs E_gamma uncertainty cross-check ===")
print("Physics: weaker gammas have poorer statistics -> larger energy uncertainty")
print("Stronger gammas have better statistics -> smaller energy uncertainty")
print()
print(f"{'E_gamma keV':>14}  {'dE keV':>8}  {'I_gamma':>10}  {'dI':>10}  {'I/dE':>8}  {'Flag'}")
print("=" * 65)

# Sort by I_gamma strength to see pattern
entries.sort(key=lambda x: x[2])

for e_val, e_unc, i_val, i_unc in sorted(entries, key=lambda x: x[2]):
    i_over_de = i_val / e_unc
    
    flags = []
    
    # --- Category 1: Weak gammas with suspiciously precise energies ---
    # I < 0.001: extremely weak, should have dE > ~0.5 keV at minimum
    if i_val < 0.001 and e_unc < 0.5:
        flags.append(f"XWEAK: I={i_val:.6f} but dE={e_unc:.3f}")
    # I < 0.003: very weak, dE should be > ~0.2 keV
    if 0.001 <= i_val < 0.003 and e_unc < 0.15:
        flags.append(f"VWEAK: I={i_val:.4f} but dE={e_unc:.3f}")
    # I < 0.01: weak, shouldn't have dE < 0.05 keV (sub-50 eV precision)
    if 0.003 <= i_val < 0.01 and e_unc < 0.05:
        flags.append(f"WEAK+HP: I={i_val:.4f} but dE={e_unc:.3f}")
    # I < 0.02: moderate weak, dE < 0.03 keV
    if 0.01 <= i_val < 0.02 and e_unc < 0.03:
        flags.append(f"MODW+HP: I={i_val:.4f} but dE={e_unc:.3f}")
    
    # --- Category 2: Strong gammas with unusually large energy uncertainties ---
    # I > 0.1 should have dE < ~1 keV
    if i_val > 0.1 and e_unc > 1.0:
        flags.append(f"STRONG+LP: I={i_val:.3f} but dE={e_unc:.2f}")
    # I > 0.05 should have dE < ~2 keV
    if i_val > 0.05 and e_unc > 2.0:
        flags.append(f"MED+LP: I={i_val:.3f} but dE={e_unc:.2f}")
    
    if flags:
        e_str = f"{e_val:.3f}"
        d_str = f"{e_unc:.4f}"
        i_str = f"{i_val:.6f}"
        di_str = f"{i_unc:.6f}"
        print(f"{e_str:>14}  {d_str:>8}  {i_str:>10}  {di_str:>10}  {i_over_de:>8.1f}  {'; '.join(flags)}")
